// Lookup maps by enemy name (lowercase)
export const ENEMY_MAP_IMAGES: Record<string, string> = {
  // Tier 1
  'thug': THUG_MAP_IMAGE,
  'super thug': SUPER_THUG_MAP_IMAGE,
  'bandit': BANDIT_MAP_IMAGE,
  'villain': VILLAIN_MAP_IMAGE,
  'criminal': CRIMINAL_MAP_IMAGE,
  'gangster': GANGSTER_MAP_IMAGE,
  // Tier 2
  'assassin': ASSASSIN_MAP_IMAGE,
  'thief': THIEF_MAP_IMAGE,
  'hoodlum': HOODLUM_MAP_IMAGE,
  'pirate': PIRATE_MAP_IMAGE,
  'bully': BULLY_MAP_IMAGE,
  // Tier 3
  'offender': OFFENDER_MAP_IMAGE,
  'hood': HOOD_MAP_IMAGE,
  'mobster': MOBSTER_MAP_IMAGE,
  'gangsta': GANGSTA_MAP_IMAGE,
  'hooligan': HOOLIGAN_MAP_IMAGE,
  // Tier 4
  'goon': GOON_MAP_IMAGE,
  'ruffian': RUFFIAN_MAP_IMAGE,
  'gang banger': GANG_BANGER_MAP_IMAGE,
  'tough guy': TOUGH_GUY_MAP_IMAGE,
  'gorilla': GORILLA_MAP_IMAGE,
};

export const ENEMY_BATTLE_IMAGES: Record<string, string> = {
  // Tier 1
  'thug': THUG_BATTLE_IMAGE,
  'super thug': SUPER_THUG_BATTLE_IMAGE,
  'bandit': BANDIT_BATTLE_IMAGE,
  'villain': VILLAIN_BATTLE_IMAGE,
  'criminal': CRIMINAL_BATTLE_IMAGE,
  'gangster': GANGSTER_BATTLE_IMAGE,
  // Tier 2
  'assassin': ASSASSIN_BATTLE_IMAGE,
  'thief': THIEF_BATTLE_IMAGE,
  'hoodlum': HOODLUM_BATTLE_IMAGE,
  'pirate': PIRATE_BATTLE_IMAGE,
  'bully': BULLY_BATTLE_IMAGE,
  // Tier 3
  'offender': OFFENDER_BATTLE_IMAGE,
  'hood': HOOD_BATTLE_IMAGE,
  'mobster': MOBSTER_BATTLE_IMAGE,
  'gangsta': GANGSTA_BATTLE_IMAGE,
  'hooligan': HOOLIGAN_BATTLE_IMAGE,
  // Tier 4
  'goon': GOON_BATTLE_IMAGE,
  'ruffian': RUFFIAN_BATTLE_IMAGE,
  'gang banger': GANG_BANGER_BATTLE_IMAGE,
  'tough guy': TOUGH_GUY_BATTLE_IMAGE,
  'gorilla': GORILLA_BATTLE_IMAGE,
};

export const getEnemyMapImage = (name: string): string | null => {
  const lower = name.toLowerCase();
  for (const [key, val] of Object.entries(ENEMY_MAP_IMAGES)) {
    if (lower.includes(key)) return val;
  }
  return null;
};

export const getEnemyBattleImage = (name: string): string | null => {
  const lower = name.toLowerCase();
  for (const [key, val] of Object.entries(ENEMY_BATTLE_IMAGES)) {
    if (lower.includes(key)) return val;
  }
  return null;
};
